
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_csk_loc4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_csk_loc4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.440059957613746e+01, 2.437002453266823e+01, 2.435677043204058e+01, 2.442246606796686e+01, 2.469398655743822e+01, 2.528547592140128e+01, 2.596849446110304e+01, 2.595832200959547e+01, 2.475539727456871e+01, 2.316773362504070e+01, 1.960165005777993e+01, 6.543081448205671e+00, 1.111020372525500e+00, 1.117486929717948e+00, 1.048983939363600e+00, 9.217483750851279e-01, 8.548121234238838e-01, 8.272485695557434e-01, 8.156770560801927e-01, 8.126908623944100e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


